import re

def log_text_safety(log_text):
    unsafe_patterns = [
        r"password",
        r"secret",
        r"token",
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, log_text, re.IGNORECASE):
            return False
    return True
